					}

					for (const member of pendingMembers) {
						let success = true;

						try {
							await bitwardenApiRequest.call(
								this,
								'POST',
								`/public/members/${member.id as string}/reinvite`,
								{},
								{},
							);
						} catch (error) {
							if (!this.continueOnFail()) throw error;
							success = false;
						}

						returnData.push(
							...this.helpers.constructExecutionMetaData(
								this.helpers.returnJsonArray({ email: member.email, success }),
								{ itemData: { item: i } },
							),
						);
					}
				} else if (operation === 'update') {
					// ----------------------------------
					//       member: update"""
